#!/usr/bin/env python3
"""Build the Q-SYS compatibility probe from Q-SYS-style include directives."""

from __future__ import annotations

import re
import sys
from pathlib import Path


QSYS_DIR = Path(__file__).resolve().parents[1]
PLUGIN_DIR = QSYS_DIR / "plugin"
ENTRY_FILE = PLUGIN_DIR / "plugin.lua"
OUTPUT_FILE = QSYS_DIR / "dist" / "f5Rocket_Compat.qplug"
INCLUDE_PATTERN = re.compile(
    r'^(?P<indent>[ \t]*)--\[\[ #include "(?P<name>[^"\r\n]+)" \]\][ \t]*(?:\r?\n)?$'
)
GENERATED_HEADER = (
    "-- GENERATED FILE\n"
    "-- Source: qsys/plugin/plugin.lua\n"
    "-- Do not edit this file manually.\n\n"
)


class BuildError(Exception):
    """Raised for an invalid include graph."""


def read_source(path: Path) -> str:
    try:
        return path.read_bytes().decode("utf-8")
    except FileNotFoundError as error:
        raise BuildError(f"missing include file: {path}") from error
    except UnicodeDecodeError as error:
        raise BuildError(f"source is not valid UTF-8: {path}") from error


def indent_text(text: str, indent: str) -> str:
    if not indent:
        return text

    lines = text.splitlines(keepends=True)
    return "".join(indent + line if line.strip() else line for line in lines)


def expand_file(path: Path, stack: tuple[Path, ...] = ()) -> str:
    resolved = path.resolve()
    if resolved in stack:
        cycle = " -> ".join(item.name for item in (*stack, resolved))
        raise BuildError(f"circular include detected: {cycle}")

    source = read_source(resolved)
    expanded = []
    next_stack = (*stack, resolved)

    for line_number, line in enumerate(source.splitlines(keepends=True), start=1):
        match = INCLUDE_PATTERN.fullmatch(line)
        if match is None:
            expanded.append(line)
            continue

        include_name = match.group("name")
        include_path = (resolved.parent / include_name).resolve()
        try:
            include_path.relative_to(PLUGIN_DIR.resolve())
        except ValueError as error:
            raise BuildError(
                f"include escapes qsys/plugin at {resolved}:{line_number}: {include_name}"
            ) from error

        included = expand_file(include_path, next_stack)
        expanded.append(indent_text(included, match.group("indent")))

    return "".join(expanded)


def build() -> int:
    expanded = expand_file(ENTRY_FILE)
    if "#include" in expanded:
        raise BuildError("generated output contains an unresolved or malformed #include")

    output = GENERATED_HEADER + expanded
    OUTPUT_FILE.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT_FILE.write_bytes(output.encode("utf-8"))

    relative_output = OUTPUT_FILE.relative_to(QSYS_DIR.parent)
    print(f"Built {relative_output} ({len(output.encode('utf-8'))} bytes)")
    return 0


def main() -> int:
    try:
        return build()
    except BuildError as error:
        print(f"Build failed: {error}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
